/**
 * Allocate a sandbox vmid and claim it onto `serverId` atomically.
 *
 * NXEON_SANDBOX has no real Proxmox to hand out ids, so this used to be
 * `990000 + (await db.server.count())` inline in worker/index.ts's `provision()`.
 * That is not a per-server sequence — `count()` is just the CURRENT number of
 * Server rows, and minting a vmid fills in a column on a row that already
 * exists (checkout inserts the PENDING Server row immediately; the PROVISION
 * job that assigns `vmid` runs later, often for several orders back-to-back
 * with no new Server row created in between). Two servers provisioned while
 * the total row count hasn't moved computed the exact same vmid, and the
 * second `prisma.server.update()` died on the `vmid` unique constraint —
 * "Provisioning failed" for a customer whose order was otherwise fine.
 *
 * Fixed the same way `allocateIp`/`allocateSshPort` above fix the identical
 * class of bug for `Server.ipAddress`/`Server.sshPort`: pick MAX(vmid)+1 and
 * claim it in one transaction under the shared advisory lock, so no second
 * caller can observe the same MAX before the first one's claim lands. Where
 * advisory locks aren't available (probed once, see `probeAdvisoryLocks`) the
 * unique-constraint retry loop is the fallback, same as the IP/port allocators.
 */
export async function allocateSandboxVmid(serverId: string): Promise<number> {
  await probeAdvisoryLocks();

  let lastErr: unknown;
  for (let attempt = 0; attempt < CLAIM_ATTEMPTS; attempt++) {
    try {
      return await db.$transaction(async (tx) => {
        await lockIpam(tx);
        const highest = await tx.server.aggregate({ _max: { vmid: true } });
        const candidate = Math.max(SANDBOX_VMID_BASE, highest._max.vmid ?? SANDBOX_VMID_BASE) + 1;
        await tx.server.update({ where: { id: serverId }, data: { vmid: candidate } });
        return candidate;
      });
    } catch (e) {
      lastErr = e;
      if (isUniqueConflict(e)) continue; // lost the race — re-read MAX and retry
      throw e;
    }
  }
  throw new Error(
    `Sandbox vmid allocation contended — gave up after ${CLAIM_ATTEMPTS} attempts` +
      (lastErr ? `: ${String((lastErr as any)?.message ?? lastErr).slice(0, 160)}` : "")
  );
}

