+        await lockIpam(tx);
+        const highest = await tx.server.aggregate({ _max: { vmid: true } });
+        const candidate = Math.max(SANDBOX_VMID_BASE, highest._max.vmid ?? SANDBOX_VMID_BASE) + 1;
+        await tx.server.update({ where: { id: serverId }, data: { vmid: candidate } });
+        return candidate;
+      });
+    } catch (e) {
+      lastErr = e;
+      if (isUniqueConflict(e)) continue; // lost the race — re-read MAX and retry
+      throw e;
+    }
+  }
+  throw new Error(
+    `Sandbox vmid allocation contended — gave up after ${CLAIM_ATTEMPTS} attempts` +
+      (lastErr ? `: ${String((lastErr as any)?.message ?? lastErr).slice(0, 160)}` : "")
+  );
+}
